function renderCards(items){return items.map(a=>`<article class="article-card"><div class="tag">${a.tag}</div><h3>${a.title}</h3><p>${a.desc}</p><div class="article-meta">${a.format.toUpperCase()} · ${a.time.toUpperCase()}</div><a href="#/artikel/${a.id}">FÖLJ ARBETET ↗</a></article>`).join('')}
document.getElementById('article-list').innerHTML=renderCards(articles);
const articleBodies={"palantir-offentlig-makt":["Den 6 november 2026 publicerades ett brittiskt tilldelningsmeddelande för BCH Palantir Foundry Platform. Avtalet tilldelades Palantir Technologies UK Ltd av The Police and Crime Commissioner for Cambridgeshire. Det angivna värdet är 10 093 202 pund exklusive moms och avtalstiden löper från 9 oktober 2026 till 8 oktober 2031. Upphandlingen beskrivs som ett avrop från ett ramavtal.","Upphandlingsbeskrivningen anger en plattform för säker inläsning, sammankoppling och analys av data från flera system inom polisverksamheten. Det offentliga meddelandet fastställer däremot inte vilka specifika register som ansluts, vilka användargrupper som får åtkomst eller vilka operativa beslut plattformen används till. Sådana slutsatser kräver avtalsbilagor, dataskyddsdokumentation och myndigheternas egna redovisningar.","BCH i avtalsnamnet ska inte i sig tolkas som bevis för att tre polisstyrkor använder samma system på identiska villkor. Den formella köparen i tilldelningsmeddelandet är Cambridgeshires Police and Crime Commissioner. Avtalets faktiska omfattning behöver därför läsas i sin helhet.","Granskningen går vidare med fem frågor: vilka data får sammanföras, vem har åtkomst, hur loggas användningen, vem ansvarar för felaktiga samband och hur kan myndigheten lämna leverantören när avtalet löper ut? Avtalets existens är belagd; svaren på dessa frågor är ännu inte fastställda i det offentliga tilldelningsmeddelandet.","<h3>Primärkällor</h3><ul><li><a href=\"https://www.contractsfinder.service.gov.uk/Notice/d7a7acf6-a793-427d-a674-ee989e704974\" target=\"_blank\" rel=\"noopener noreferrer\">Contracts Finder – tilldelningsmeddelande</a></li><li><a href=\"https://opentenders.co.uk/tenders/bch-palantir-foundry-platform-0821d9d1\" target=\"_blank\" rel=\"noopener noreferrer\">OpenTenders – återgivning av tilldelningen</a></li></ul>"],"europas-ai-infrastruktur":["Google meddelade den 5 november 2026 att bolaget planerar sitt första datacenter i Wyoming och beskriver satsningen som en långsiktig investering på 17 miljarder dollar. Projektet presenteras tillsammans med Tallgrass Energy, Black Hills Energy, American Electric Power och Related Digital.","En central del av energiplanen är ett planerat bränslecellsprojekt på 702 MW nära Cheyenne. American Electric Power meddelade den 14 oktober att bolaget planerar att investera omkring fyra miljarder dollar i projektet genom Cheyenne Fuel Cell LLC. Google ska köpa elen genom ett långsiktigt kraftköpsavtal på 20 år. AEP uppger att bolaget kontrollerar cirka 92 procent av projektbolaget och att fonder rådgivna av Basalt Infrastructure Partners äger knappt 8 procent. Full drift väntas enligt AEP i slutet av 2028.","Den 6 november meddelade Crusoe att Google förvärvat Crusoes förberedda datacenterområde i sydöstra Wyoming. Det visar hur utveckling av AI-infrastruktur kan delas upp mellan markförberedelser, energipartnerskap, fastighetsägande och slutlig drift. De offentliga uppgifterna som hittills redovisats anger inte köpeskillingen för Crusoes överlåtelse.","Projektet väcker frågor som sträcker sig bortom teknik: vem bär kostnaden för nätanslutningar, vad händer om efterfrågan blir lägre än planerat, hur fördelas riskerna i kraftköpsavtalet och vilka klimatresultat kan faktiskt mätas? Googles löfte att stå för elen och den infrastruktur som drivs av bolagets tillväxt är ett företagsåtagande; utfallet behöver följas mot avtal, tillstånd och faktiska investeringar.","AI-industrins strategiska position avgörs därför inte enbart av modeller och halvledare. Mark, kraftproduktion, elnät, kylning, finansiering och långsiktiga avtal blir delar av samma konkurrens om infrastrukturen.","<h3>Primärkällor</h3><ul><li><a href=\"https://blog.google/innovation-and-ai/infrastructure-and-cloud/global-network/wyoming-data-center/\" target=\"_blank\" rel=\"noopener noreferrer\">Google – Wyoming, 5 november 2026</a></li><li><a href=\"https://www.aep.com/news/stories/view/12314/\" target=\"_blank\" rel=\"noopener noreferrer\">AEP – 702 MW bränslecellsprojekt, 14 oktober 2026</a></li><li><a href=\"https://www.reuters.com/business/google-acquires-wyoming-data-center-site-ai-infrastructure-firm-crusoe-2026-11-06/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – Googles förvärv av Crusoes område, 6 november 2026</a></li></ul>"],"hormuz-sjofart":["IMO:s råd uppger den 6 november att 25 sjömän har dödats sedan Hormuzkonflikten började och att minst 130 attacker mot kommersiella fartyg har verifierats. Samtidigt anger IMO:s separata lista över bekräftade incidenter 129 incidenter per den 6 november. Dessa två tal beskriver olika sammanställningar och ska inte slås ihop till ett enda mått.","IMO:s pressmeddelande beskriver attacken mot M/T Velos Sapphire som inträffad den 5 november. IMO:s incidentlista daterar fartygets skada till den 4 november, cirka 50 nautiska mil norr om Madinat ash Shamal i Qatar, och anger ett dödsfall. Datumskillnaden redovisas öppet.","Reuters rapporterar att fartyget träffades av en explosion som misstänks ha orsakats av en robot och att en sjöman senare hittades död. Fartygets operatör uppgav att besättningen släckte branden och att ingen annan besättningsmedlem skadades. Orsak och ansvar måste hållas isär från den dokumenterade skadan.","Den 7 november gav Filippinernas Department of Migrant Workers en mer detaljerad besättningsbild. Sekreteraren Hans Leo Cacdac uppgav i intervju med GMA News att 22 filippinska sjömän fanns ombord: en omkom, en skadades och 20 var oskadda. Det skiljer sig från Velos Tankers tidigare uppgift att ingen annan besättningsmedlem skadats. DMW sade att den skadades tillstånd ännu skulle klarläggas och att myndigheten samordnade med bemanningsagenturen om säkerhet och repatriering. Detta är en myndighetsföreträdares uppgift återgiven i intervju, inte en separat skriftlig DMW-bulletin. <a href='https://www.gmanetwork.com/news/pinoyabroad/dispatch/1008636/dmw-filipino-seafarer-killed-another-hurt-in-persian-gulf-tanker-attack/story/'>GMA News – intervju med DMW:s sekreterare, 7 november 2026</a>.\nDen här artikeln avgränsas till de uppgifter som IMO och Reuters publicerat. UKMTO:s separata incidentvarningar och andra fartygshändelser ska föras in först när varje händelse kan matchas mot en egen primärnotis.","<h3>Primärkällor</h3><ul><li><a href=\"https://www.imo.org/en/mediacentre/pressbriefings/pages/imo-council-c138-urges-stronger-protection-of-seafarers-amid-threats-to-global-shipping-.aspx\" target=\"_blank\" rel=\"noopener noreferrer\">IMO – rådets uttalande, 6 november 2026</a></li><li><a href=\"https://www.imo.org/en/mediacentre/hottopics/pages/middle-east-highlighted-incidents.aspx\" target=\"_blank\" rel=\"noopener noreferrer\">IMO – bekräftade incidenter, 6 november 2026</a></li><li><a href=\"https://www.reuters.com/world/one-seafarer-killed-missile-attack-tanker-gulf-2026-11-06/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – dödsoffer på Velos Sapphire, 6 november 2026</a></li></ul>"],"synkronicitetsprotokollet":["Detta projekt utvecklar en dokumentär metod för att undersöka upplevda sammanträffanden. En tidslinje kan visa att två händelser inträffade nära varandra. Den kan inte ensam visa att den ena orsakade den andra.","Varje observation delas upp i tre lager: dokumenterade fakta, personlig iakttagelse och tolkning. Källor, datum, alternativa förklaringar och osäkerhet ska följa med varje post."],"sofia-staden-under-staden":["Sofia bär flera historiska lager ovanpå och under dagens gatunät. Kyrkor, ruiner och arkeologiska lämningar gör stadens historia synlig – men en stark berättelse måste också tåla kontroll mot arkeologiska och historiska källor.","Särskild källkontroll krävs kring Tsar Samuil. Hans gravtradition är främst knuten till basilikan Sankt Achilleios vid Lilla Prespasjön; den får inte utan belägg flyttas till Sankt Sofia i Sofia."],"europas-strategiska-ravaror":["Kampen om strategiska råvaror handlar om mer än fyndigheter. Förädling, energi, transporter, miljötillstånd och långsiktiga köpeavtal avgör vem som faktiskt kan leverera material till Europas industri.","Artikeln ska skilja mellan reserver, resurser, produktion och planerade projekt. Ägarstruktur och offentligt stöd ska beläggas med bolagsrapporter och myndighetsmaterial."],"nvidia-som-sakerhet":["Två olika finansieringsmodeller diskuteras ofta som om de vore samma sak. I den ena används börsnoterade aktier som pant för lån. I den andra används servrar eller GPU-utrustning som säkerhet. Riskerna och värderingsfrågorna skiljer sig åt.","Granskningen ska följa belåningsgrad, värdering, marginalkrav, refinansiering och risken att hårdvara snabbt tappar andrahandsvärde. Varje exempel kräver primärkälla."],"det-stora-och-lilla-fangelset":["Samir Geagea frigavs den 26 juli 2005 efter att en amnestilag antagits i Libanons parlament. Händelsen ägde rum i efterdyningarna av Cederrevolutionen och Syriens militära tillbakadragande.","En historisk granskning måste rymma både hans anhängares berättelse om politisk fångenskap och de allvarliga brottmålsdomar som föregick fängslandet. Rättegångarna, amnestin och hans egna uttalanden ska återges med primärkällor och oberoende perspektiv."],"kyrkor-som-overlevde-imperierna":["Europas kyrkor är inte en enda berättelse om överlevnad. Varje byggnad måste följas genom sin egen byggnadshistoria, sina församlingar, skador, ägarförhållanden och restaureringsbeslut. Wiesbaden, Warszawa och Prag utgör seriens första jämförande kärna; Sofia och Varna är möjliga fortsättningar.","Serien skiljer mellan byggnadens fysiska kontinuitet, liturgisk användning, församlingens överlevnad och senare återuppbyggnad. Ett krigsskadat eller återinvigt kyrkorum får inte beskrivas som obrutet om källorna visar avbrott."],"fennoskandien-urberg-skog-hast":["Fennoskandien är ett varierat landskap, inte en enhetlig historisk zon. Urberg, skog, vattenvägar, jordbruk och hästhållning har formats av olika klimat, näringar och samhällen.","Arctial och hästlandskapet i Kvikant är ett nutida delcase om mark, energi och djurhållning – inte i sig ett bevis för en obruten fennoskandisk hästtradition. Huvudartikeln kräver separata geologiska, skogshistoriska, arkeologiska och hästhistoriska källor."],"skaga-offerkyrkan-tiveden":[
"Skaga stavkyrka ligger i Tiveden, väster om sjön Unden. Den första kyrkan på platsen beskrivs av Svenska kyrkan som en sägenomspunnen byggnad från 1100-talet. Riksantikvarieämbetets genomgång av äldre beskrivningar anger att den sannolikt var en tidigmedeltida stavkyrka. Skara stiftshistoriska sällskap uppger att kapellet var helgat åt Johannes Döparen och låg vid en offerkälla. Den exakta grundläggningshistorien måste skiljas från berättelsen om Ramunders dotter Skaga: den senare är en lokal tradition, inte en samtida byggnadsinskrift.",
"Platsen bär flera historiska lager. En låg kulle, kyrkogården och källan har varit delar av platsens religiösa geografi. Skara stiftshistoriska sällskap beskriver hur offerkällan ännu finns kvar och hur oxiderade mynt kan ses på dess botten. Det är en nutida iakttagelse av platsen, inte i sig en arkeologisk datering av varje mynt eller ett bevis för att alla äldre offertraditioner har samma ursprung.",
"Den kyrkohistoriska uppsatsen av Karl Bäckgren från 1933 återger äldre berättelser om att kapellet återupptäcktes efter att ha vuxit igen. Bäckgren jämför detta motiv med sägner om andra stavkyrkor och varnar indirekt för att behandla återupptäcktsberättelserna som unik historisk dokumentation. I vår läsning får sägnen finnas kvar som en del av platsens minne, men den får inte ersätta byggnadsarkeologi och arkiv.",
"Skaga är därför intressant just i mötet mellan institutionell kyrkohistoria och folklig religiositet. Källmaterialet visar att kapellet var en verklig kyrkobyggnad med inventarier, visitationer och gudstjänster. Det visar också att offerbruket blev föremål för upprepade kyrkliga konflikter. Hur människor själva förstod dessa handlingar måste undersökas i de historiska formuleringarna, inte reduceras till senare etiketter.",
"Primärkällor och vidare läsning: <a href='https://www.svenskakyrkan.se/karlsborg/skaga-stavkyrka' target='_blank' rel='noopener noreferrer'>Karlsborgs pastorat – Skaga stavkyrka</a> · <a href='https://www.raa.se/publicerat/9172093412.pdf' target='_blank' rel='noopener noreferrer'>Riksantikvarieämbetet – Kyrkan brinner!, rapport 2004:2</a> · <a href='https://skarastiftshistoriska.nu/wp-content/uploads/2025/12/Medlemsblad2504.pdf' target='_blank' rel='noopener noreferrer'>Skara stiftshistoriska sällskap, medlemsblad 4/2025</a> · <a href='https://runeberg.org/kyrkohist/1933/0133.html' target='_blank' rel='noopener noreferrer'>Karl Bäckgren, Skaga offerkyrka i Tiveden, 1933</a>"
],
"skaga-inventarierna-silverlojan":[
"Skagas historia går att följa genom inventarier och visitationer – och genom föremål som inte längre finns kvar. Karl Bäckgrens genomgång från 1933 återger ett inventarium från 1794 med nattvardssilver, kalkar, textilier, psalmbok, en äldre klocka och en silverlöja med kedja. Den silverklädda fisken beskrevs som en gåva från en förnäm man på Ramsnäs mot slutet av 1600-talet, avsedd att hjälpa siklöjefisket i sjön Unden att åter bli givande.",
"Traditionen om silverlöjan har en konkret föremålshistoria. Bäckgren skriver att den fortfarande hängde ovanför predikstolen på 1790-talet men att den vid visitation 1805 uppgavs ha varit stulen sedan flera år. Den var alltså inte ett föremål som med säkerhet fanns kvar vid rivningen 1826. I dagens kyrka finns en silverlöja ovanför predikstolen enligt Svenska kyrkans beskrivning, men den moderna placeringen ska inte blandas ihop med det förlorade originalföremålets proveniens.",
"Även björnhuden har flera lager av dokumentation och tradition. Bäckgren återger en äldre beskrivning av ett björnskinn nedanför altaret och kyrkoräkenskaper som nämner en björnhud såld 1665 för 12 daler kopparmynt samt en gåva på 12 daler silvermynt 1708 efter att sockenbor dödat en björn. Skinnet som användes i kyrkorummet har därmed en lokal och ekonomisk historia; det behöver inte tolkas som ett direkt bevis för en förkristen kult.",
"År 1687 begärde kapellanen i Undenäs att kapellet skulle raseras med hänvisning till offrande och vad han kallade vidskepelse. I 1747 års domkapitelsmaterial återkommer den kyrkliga kritiken. Bäckgrens återgivning av visitationerna visar att konflikten var långvarig och att kapellets skick samtidigt försämrades. Den äldre kyrkan såldes på auktion och revs 1826. Skara stiftshistoriska sällskap uppger att bland föremålen som såldes fanns en avbildning av Johannes Döparens huvud inristad på ett silverfat, försilvrade nattvardskärl, en silveraktig löja och en kyrkklocka. Klockan ska senare ha använts som vällingklocka vid Sättra bruk.",
"Det går ännu att följa föremålens efterliv genom lokala uppgifter om återbrukade byggnadsdelar och genom minnesstenen som restes 1919. Men en fullständig föremålslista kräver kontroll av auktionsprotokoll, inventarier och kyrkoarkiv. Den här artikeln skiljer därför mellan Bäckgrens återgivning av äldre handlingar, senare lokalhistoriska uppgifter och sådant som fortfarande måste spåras i originalarkiv.",
"Primärkällor och vidare läsning: <a href='https://runeberg.org/kyrkohist/1933/0136.html' target='_blank' rel='noopener noreferrer'>Bäckgren 1933, björnhud och kyrkoräkenskaper</a> · <a href='https://runeberg.org/kyrkohist/1933/0138.html' target='_blank' rel='noopener noreferrer'>Bäckgren 1933, inventarium och silverlöja</a> · <a href='https://runeberg.org/kyrkohist/1933/0139.html' target='_blank' rel='noopener noreferrer'>Bäckgren 1933, kyrklig kritik av offerbruket</a> · <a href='https://runeberg.org/kyrkohist/1933/0141.html' target='_blank' rel='noopener noreferrer'>Bäckgren 1933, avvecklingen 1826</a> · <a href='https://skarastiftshistoriska.nu/wp-content/uploads/2025/12/Medlemsblad2504.pdf' target='_blank' rel='noopener noreferrer'>Skara stiftshistoriska sällskap, 2025</a>"
],
"skaga-stavkyrkorna-ateruppbyggnad":[
"Skaga har haft tre kyrkobyggnader på samma plats. Den första, en medeltida träkyrka, revs 1826. Den andra var den stavkyrkeinspirerade rekonstruktion som uppfördes 1957–1958 under landsantikvarien Erik Salvén och arkitekten Erik Lundberg och invigdes 1960. Riksantikvarieämbetets rapport från 2004 beskriver hur den byggdes med resta, tjärade plankor, brant spåntäckt sadeltak och ett enkelt kyrkorum öppet upp till nocken.",
"Den andra kyrkan brann ned till grunden kring årsskiftet 1999–2000. Här finns en viktig källskillnad: Karlsborgs pastorats nuvarande webbtext beskriver branden som vådabrand, medan Riksantikvarieämbetets rapport från 2004 säger att brandorsaken inte var klarlagd. Rapporten klassificerar uttryckligen Skaga bland bränder med okänd orsak. Innan brandutredningen har återfunnits bör redaktionen redovisa skillnaden och inte slå fast en brandorsak.",
"Beslutet blev att bygga upp kyrkan igen. Den tredje kyrkan återinvigdes midsommaren 2001. Riksantikvarieämbetet beskriver hur den uppfördes efter 1950-talets ritningar, men med ett mindre vapenhus i söder som enligt äldre beskrivningar ska ha funnits på den första kyrkan. Svenska kyrkan anger att den gamla altarhällen – trappstenen från föregående kyrka – var det enda som kunde återanvändas. Det är en viktig skillnad mellan materiell kontinuitet och en arkitektonisk rekonstruktion.",
"Skaga blev dessutom förebild för en annan stavkyrka. Skara stiftshistoriska sällskaps medlemsblad 4/2025 berättar att Sven Viksten 1987 reste till Undenäs för att hämta ritningarna till Skaga, eftersom Färila pastorat ville använda kyrkan som förebild för en ny stavkyrka i Kärböle. Därmed blev Skaga inte bara en rekonstruktion av ett äldre byggnadsskick, utan också en modell som inspirerade ett senare kyrkobyggnadsprojekt.",
"Jämförelsen med Kärböle kräver dock en egen byggnadshistorik. Skaga och Kärböle är två skilda platser och församlingar; den ena kyrkans historia får inte överföras till den andra. Den gemensamma länken som medlemsbladet belägger är ritningsförmedlingen och Skagas roll som förebild.",
"Primärkällor och vidare läsning: <a href='https://www.raa.se/publicerat/9172093412.pdf' target='_blank' rel='noopener noreferrer'>Riksantikvarieämbetet – Kyrkan brinner!, s. 38</a> · <a href='https://www.svenskakyrkan.se/karlsborg/skaga-stavkyrka' target='_blank' rel='noopener noreferrer'>Karlsborgs pastorat – Skaga stavkyrka</a> · <a href='https://skarastiftshistoriska.nu/wp-content/uploads/2025/12/Medlemsblad2504.pdf' target='_blank' rel='noopener noreferrer'>Skara stiftshistoriska sällskap – Skaga och Kärböle stavkyrkor</a>"
],
"tsar-samuil-aterforandet":[
"Den 3 oktober 2026 överlämnade Grekland till Bulgarien de kvarlevor som identifierats som tsar Samuils vid en ceremoni i Thessaloniki. Samma överlämningsprotokoll omfattade antropologiskt material från andra gravstrukturer vid basilikan Sankt Achilleios på ön i Lilla Prespasjön. I utbyte överförde Bulgarien 48 kyrkliga reliker till Grekland. Kvarlevorna fördes därefter till Sofia och placerades i en marmorsarkofag i Sankt Sofia-kyrkan.",
"Detta förändrar den nutida historien om Samuils gravplats. Den arkeologiska fyndplatsen är basilikan Sankt Achilleios vid Lilla Prespa, där kvarlevorna undersöktes och förvarades i Thessaloniki före återförandet. Sankt Sofia i Sofia är den nya viloplatsen efter den statliga ceremonin 2026. De två platserna fyller alltså olika roller: fyndplats och historisk gravkontext å ena sidan, ny gravplats och nationell minnesplats å den andra.",
"Den 8 oktober presenterades preliminära antropologiska resultat av forskare från Bulgariens nationella arkeologiska institut med museum och BAS-institutet för experimentell morfologi, patologi och antropologi. De uppgav en uppskattad dödsålder på 60–70 år och en längd omkring 173 centimeter. Skelettet uppvisar degenerativa förändringar i ryggrad och leder. Forskarna identifierade också en underarmsfraktur som läkt med en falsk led, vilket ska ha gett en betydande funktionsnedsättning i vänster arm.",
"Resultaten är preliminära, inte en fullständig biografi. Forskarna har aviserat ett bredare program med radiokoldatering, gammalt DNA, stabila isotoper och en ny rekonstruktion av Samuils huvud. Det är dessa kommande undersökningar – och hur resultaten redovisas – som kan fördjupa kunskapen om individen och gravmiljön. De ska inte förväxlas med de historiska krönikornas berättelser om härskaren.",
"En detalj kräver särskild källkontroll: BTA:s rapport från överlämningsdagen anger att kvarlevorna upptäcktes 1969, medan annan internationell rapportering beskriver upptäckten som 1965. Denna skillnad bör kontrolleras mot utgrävningsjournaler och museets accessionhandlingar innan ett exakt upptäcktsår används som fastslaget. Även identifieringen av de olika gravarnas individer måste återges med forskarnas egna grader av säkerhet.",
"Din tidigare iakttagelse av kistan och Chi-Rho-symbolen i Sankt Sofia ska behandlas som ett separat observationsspår. Den kan beskrivas som vad du såg på platsen, med datum och bilddokumentation om sådan finns. Den får inte utan en dokumenterad koppling sägas vara en del av Samuils grav eller den nya sarkofagens officiella ikonografi.",
"Primärkällor och vidare läsning: <a href='https://www.bta.bg/en/news/1217016-bulgaria-greece-sign-protocols-on-tsar-sameul-s-remains-transfer' target='_blank' rel='noopener noreferrer'>BTA – överlämningsprotokollen, 3 oktober 2026</a> · <a href='https://www.bta.bg/en/news/culture/1220275-preliminary-examination-of-tsar-samuel-s-remains-reveals-chronic-illnesses-seve' target='_blank' rel='noopener noreferrer'>BTA – preliminära antropologiska resultat, 8 oktober 2026</a> · <a href='https://mfa.bg/en/news/49287' target='_blank' rel='noopener noreferrer'>Bulgariens utrikesministerium – ceremonin i Sofia</a> · <a href='https://bnrnews.bg/en/post/536959/tsar-samuils-remains-placed-in-a-marble-sarcophagus-in-sofia' target='_blank' rel='noopener noreferrer'>Radio Bulgaria – sarkofagen i Sankt Sofia</a>"
],
"osiris-redaktionell-tillampning":[
"OSIRIS är ett OSINT-system – Open Source Intelligence & Reconnaissance Integrated System – som samlar flera öppna datadomäner i en gemensam lägesbild. Projektets offentliga kodbas beskriver bland annat flygdata, maritima noder, offentliga kameror, jordbävningar, bränder, nyhetsflöden, väder, satelliter, cyberindikatorer, konfliktområden, sanktionssökning och offentliga Telegram-kanaler. Systemet bygger bland annat på Next.js och MapLibre och använder API-rutter för att hämta och presentera data från externa källor.",
"För FOLKTRIBUNALEN är den centrala nyttan inte att låta en karta avgöra vad som är sant. OSIRIS kan användas som en upptäckts- och sammanställningsyta: hitta en händelse, lokalisera relevanta platser, lägga tidsstämplar bredvid varandra, identifiera berörda aktörer och länka vidare till ursprungskällan. En flyg- eller fartygsposition, en kamerabild eller en nyhetsnotis är en signal som behöver kontrolleras – inte automatiskt ett bevis för en större berättelse.",
"Det redaktionella arbetsflödet kan byggas i sex steg. Först skapas ett ärende med en tydlig fråga och geografisk/tidsmässig avgränsning. Därefter samlas öppna källor in och varje observation får källa, insamlingstid, publiceringstid, geografisk precision och källtyp. I tredje steget byggs en tidslinje och en karta. I fjärde steget jämförs uppgifter mellan oberoende källor och motsägelser flaggas. I femte steget formuleras alternativa hypoteser och vad som skulle kunna falsifiera dem. Sist granskar en redaktör materialet och godkänner vilka påståenden som får gå vidare till publicering.",
"OSIRIS innehåller även OI Assist och OI Forecast enligt projektets README. Forecast-funktionen beskrivs som en simuleringsbaserad prognos där flera aktörer spelas mot varandra i parallella scenarier och resultatet vägs mot källor, marknadspriser och en statistisk baslinje. För redaktionen ska sådana resultat märkas som scenarier eller prognoser, aldrig som observerade fakta. Prognosen måste bära sina källor, antaganden, osäkerheter och modellversion.",
"Den praktiska kopplingen till FOLKTRIBUNALEN bör vara en Evidence Passport-post per centralt påstående: exakt formulering, källa, källans ursprung, tidpunkt, stödjande utdrag, motstridiga uppgifter, geografisk precision, bedömd säkerhet och ansvarig redaktör. När en ny uppgift motsäger en tidigare ska systemet markera vilka delar av tidslinjen och artikeln som påverkas, bevara föregående version och kräva mänskligt godkännande innan texten ändras. Det ligger i linje med vår metod för att hålla fakta, analys och tolkning åtskilda.",
"Gränsen mellan befintligt och planerat måste vara synlig. OSIRIS-kodbasen och dess dokumenterade moduler finns i det publika GitHub-projektet. README beskriver API-rutter, MCP-gränssnitt och ett antal datakällor. Det betyder inte att varje källa fungerar utan avbrott, att alla uppgifter är realtidsdata eller att OSIRIS redan är integrerat med FOLKTRIBUNALENs publiceringssystem. Den redaktionella integrationen som beskrivs här är en tillämpningsmodell; den måste byggas och testas separat innan den kan kallas driftsatt.",
"Projektkälla: <a href='https://github.com/simplifaisoul/osiris' target='_blank' rel='noopener noreferrer'>OSIRIS – GitHub repository</a> · <a href='https://osirisai.live' target='_blank' rel='noopener noreferrer'>OSIRIS – webbgränssnitt</a> · <a href='https://github.com/simplifaisoul/osiris/blob/master/README.md' target='_blank' rel='noopener noreferrer'>README och systemöversikt</a>"
]};

articleBodies["hormuz-sjofart"] = ["<h3>Priset rör sig före farleden</h3>\n<p>Under den tidiga handeln den 5 november, klockan 04.26 GMT, låg Brent kring 93,82 dollar per fat och amerikansk WTI kring 86,92 dollar. Det var en ögonblicksbild, inte dagens slutkurs. Vid handelsdagens avräkning hade priserna vänt upp: Brent stängde på 98,29 dollar, upp 3,88 procent, och WTI på 90,52 dollar, upp 2,72 procent. Dagen före hade båda riktmärkena fallit med mer än åtta procent. De tidiga noteringarna och slutkurserna beskriver alltså olika tidpunkter samma dag.</p>\n<p>Reuters kopplade marknadsreaktionen till Republikanernas förluster i veckans kongressval i USA. Investerare och analytiker bedömde att ett försvagat politiskt läge för president Donald Trump kan minska sannolikheten för en ny militär upptrappning mot Iran och öka utrymmet för en uppgörelse. Det är en marknadstolkning – inte ett besked om att kriget är på väg att avslutas.</p>\n<p>Reuters återgav samtidigt JPMorgans bedömning att oljemarknaden åter gått in i ett överskott: omkring 1,1 miljoner fat per dag i september och 1,4 miljoner i oktober. Analytiker uppgav också att råoljeleveranserna genom Hormuz närmat sig nivåerna före kriget, men till högre kostnad. Den uppgiften bör läsas som en bedömning från marknadsaktörer, inte som ett nytt officiellt dygnstal för trafiken genom sundet.</p>\n<p>Det är här skillnaden blir viktig. Ett terminspris reagerar på förväntningar om framtida utbud. En redare, besättning eller försäkringsgivare måste bedöma om ett fartyg kan passera en viss rutt i dag, till vilken premie och med vilken risk.</p>\n<h3>Sydkorea flyttar beredskapen närmare Oman</h3>\n<p>Samma dag rapporterade Reuters att Sydkoreas försvarsministerium planerar att utvidga den marina Cheonghae-enhetens operationsområde närmare Hormuzsundet. Enheten har sedan 2009 varit verksam i Adenviken med uppgift att skydda civil sjöfart mot piratverksamhet.</p>\n<p>Planen är att utvidga operationsområdet till öppet vatten söder om Oman, i närheten av hamnen Duqm – omkring 650 kilometer från Hormuzsundet. Den befintliga styrkan består av en jagare på cirka 4 400 ton, en marin helikopter, mindre patrullbåtar och omkring 300 personer. Reuters rapporterade att Sydkorea dessutom planerar att tillföra ett P-8A Poseidon-maritimt spaningsflygplan och öka personalstyrkan med 75 personer.</p>\n<p>Sydkoreanska Financial News redovisade mer detaljer med hänvisning till försvarsministeriet: en bomb- och ammunitionsröjningsgrupp samt obemannade undervattensfarkoster, obemannade ytfarkoster och fjärrstyrda undervattensfarkoster. Enligt den rapporteringen ska utrustningen även förbereda Sydkorea för en möjlig framtida internationell minröjningsinsats i Hormuz efter att kriget mellan USA och Iran har upphört.</p>\n<p>Detta är inte detsamma som att Sydkorea redan har skickat en minröjningsstyrka in i Hormuz. Förslaget kräver fortsatt nationellt godkännande. Reuters uppgav att regeringen ska lägga fram en begäran om att förlänga insatsen efter dess nuvarande slutdatum vid utgången av 2026. Financial News beskrev en process där förslaget först ska vidare genom regeringens beslutsordning och därefter till nationalförsamlingen.</p>\n<p>CNA, med uppgifter från AFP och en sydkoreansk försvarstalesperson, preciserade den politiska begränsningen: uppdraget ska vara icke-stridande och bedrivas självständigt från allierade styrkor. Operationsområdet ska ligga i öppet vatten söder om Oman. Spaningsflyget ska inte rikta in sig på eller övervaka iranskt territorium, iranskt territorialvatten eller själva sundets inre passage. Sydkoreas president Lee Jae Myung har tidigare sagt att landet inte ska gå in i kriget på ett sätt som drar in landet i strid.</p>\n<p>Det är en avgränsad men strategiskt betydelsefull position: skydda egna medborgare och handelsintressen, bygga kapacitet för sjösäkerhet och samtidigt undvika ett formellt deltagande i kriget.</p>\n<h3>Ett ekonomiskt beroende med militär geografi</h3>\n<p>Sydkoreas intresse är inte abstrakt. Enligt uppgifter från landets industriministerium, återgivna av Reuters, kom omkring 70 procent av Sydkoreas oljeimport från Mellanöstern under 2025. Merparten av dessa leveranser passerar Hormuz.</p>\n<p>USA:s energimyndighet EIA uppskattade oljeflödet genom sundet till i genomsnitt 20,9 miljoner fat per dag under första halvåret 2025 – ungefär en femtedel av världens konsumtion av petroleumvätskor och omkring en fjärdedel av den sjöburna oljehandeln. EIA:s senare kvartalstabell visar 21,6 miljoner fat per dag under fjärde kvartalet 2025, 14,9 miljoner under första kvartalet 2026 och 4,9 miljoner under andra kvartalet 2026.</p>\n<p>Siffrorna får inte användas som om de beskrev trafiken den 5 november. EIA:s tabell bygger på data till och med juni 2026 och myndigheten varnar uttryckligen för att AIS-signaler från fartyg i Hormuz har blivit särskilt opålitliga sedan slutet av februari. Uppgifterna revideras därför löpande. Reuters rapporterade den 5 november att analytiker bedömde att råoljeflödena senare återhämtat sig nära nivåerna före kriget, men till högre kostnad. De två uppgifterna gäller olika tidsperioder och olika underlag.</p>\n<p>För Sydkorea handlar frågan alltså både om dagens eskort- och skyddsuppdrag och om förmågan att återställa en farled efter en konflikt. Minröjning, sjöövervakning, eskort, försäkring och diplomatiskt tillträde är skilda delar av samma försörjningskedja.</p>\n<h3>Färska incidenter – och påståenden som ännu inte kan räknas som bekräftade</h3>\n<p>UK Maritime Trade Operations (UKMTO) rapporterade den 3 november två separata händelser. I incident 195-26 uppgav ett tankfartygs säkerhetsansvarige att fartyget träffats av två okända projektiler i maskinrummet, omkring 14 nautiska mil nordost om Lima i Oman. Inga personskador eller miljöeffekter rapporterades då. I incident 194-26 återgav UKMTO en rapport från Indiens regering om en attack mot en indiskbemannad dhow på väg ut genom Hormuz. Omans flotta hade räddat överlevande; fartygets status var fortfarande okänd i UKMTO:s rapport.</p>\n<p>En Reuters-rapport publicerad den 5 november redovisade då minst fem fartyg som rapporterat incidenter sedan den 1 november och 35 fartygsincidenter under oktober. Det var en tidigare ögonblicksbild. UKMTO:s egen Voluntary Reporting Area Weekly Overview No. 14, producerad den 6 november och med rapporteringsperiod till och med den 4 november, redovisar elva rapporterade attacker under den senaste veckan: åtta i Hormuzsundet och tre i Persiska viken. Av dessa elva uppges tre fartyg ha sjunkit, fem ha behövt assistans och tre ha fortsatt sin resa. UKMTO uppger också att 63 av 88 projektilangrepp sedan den 6 juli inträffat längs den södra rutten. Detta är UKMTO:s rapporterade incidentbild, inte en attribution av ansvar till en viss aktör.</p>\n<p>UKMTO:s trafikdata visar samtidigt 170 utgående och 155 inkommande passager under de senaste sju dagarna – sammanlagt omkring 65 procent under förkonfliktnivån. AIS-observerade passager steg till 71 från 64 veckan före. UKMTO anger att USA-rapporterade, assisterade passager låg ungefär tre gånger över AIS-observationerna och att omkring 80 procent av passagerna fortfarande var energibärare. Men UKMTO skriver uttryckligen att de amerikanska NCAGS-siffrorna och de sammanlagda transitstalen inte kan verifieras oberoende av organisationen. De ska därför inte behandlas som fullständigt AIS-bekräftade fartygsrörelser.</p>\n<p>UKMTO:s veckorapport räknar 96 rapporterade incidenter i Hormuzsundet sedan den 28 februari och 155 konfliktrelaterade incidenter i hela dess rapporteringsområde hittills under året. Joint Maritime Information Center (JMIC) redovisade i Advisory Update 111 den 5 november i stället 172 bekräftade fartygsincidenter sedan den 1 mars. IMO:s separata sammanställning angav 129 bekräftade incidenter i Hormuz och den vidare Mellanösternregionen per den 5 november. Dessa totalsiffror har olika geografiska områden, tidsperioder och verifieringsdefinitioner och får inte adderas eller presenteras som om de mätte samma sak.</p>\n<p>JMIC bedömde hotnivån i själva Hormuzsundet som SEVERE och i Persiska viken som SUBSTANTIAL. Samma rapport uppskattade att omkring 229 kommersiella fartyg låg stilla vid de större ankarplatserna öster om sundet; bedömningen byggde på intern AIS-analys och uteslöt fartyg som inte sände AIS. Det är en indikation på fortsatt köbildning, inte ett fullständigt register över alla fartyg i området.</p>\n<h4>VELOS SAPPHIRE och explosionen vid Khasab</h4>\n<p>UKMTO:s incident 196-26 gäller ett Marshallöarna-flaggat tankfartyg som den 4 november träffades av två okända projektiler omkring 50 nautiska mil norr om Madinat ash Shamal i Qatar. UKMTO:s veckorapport uppgav att fartyget drev och fick stöd av lokala myndigheter. IMO:s lista identifierade fartyget som MT VELOS SAPPHIRE (IMO 9321201) och angav den 5 november att det var skadat, utan rapporterad förorening, och att en sjöman saknades.</p>\n<p>Den 6 november bekräftade den grekiska fartygsförvaltaren Velos Tankers att den saknade sjömannen hade hittats dödligt skadad ombord. Enligt bolagets uttalande var övriga besättningsmedlemmar oskadda, branden efter explosionen släcktes av besättningen och ingen förorening hade rapporterats. Fartyget fördes till Khalifa Bin Salman-hamnen i Bahrain, där en utredning ska inledas. Skadorna på skrovet bedömdes fortfarande. Uppgiften om dödsfallet är en partsuppgift från fartygsförvaltaren, återgiven av Reuters; IMO:s offentliga ögonblicksbild från den 5 november listar fortfarande personen som saknad. IMO:s rådsmeddelande och generalsekreterarens avslutningsanförande den 6 november är senare primärkällor och bekräftar att personen är den 25:e sjömansförlusten sedan konfliktens början. Händelsedatumet anges olika i de tidigare incidentposterna och det senare uttalandet; avvikelsen redovisas öppet. Orsaken beskrevs av bolaget som sannolikt en missil, men någon ansvarig aktör har inte fastställts.</p>\n<p>Den 7 november tillkom en motuppgift från Filippinernas Department of Migrant Workers. I en intervju med GMA News uppgav arbetsmarknadsminister Hans Leo Cacdac att 22 filippinska sjömän fanns ombord: en hade dött, en annan var skadad och 20 var oskadda. Cacdac sade att myndigheten fortfarande försökte fastställa den skadades tillstånd. Detta står i konflikt med Velos Tankers uppgift om att inga andra besättningsmedlemmar skadats. <strong>PARTSUPPGIFT / OBEROENDE RAPPORTERING:</strong> GMA News dokumenterar ministerns uttalande, men någon medicinsk rapport eller oberoende bekräftelse av skadans art och nuvarande tillstånd har inte identifierats. Besättningsstatusen är därför inte slutligt klarlagd.</p>\n<p>Det finns också en tidsavvikelse som bör redas ut före publicering: Velos Tankers angav händelsetiden till 01.15 lokal tid den 5 november, medan UKMTO:s första rapport anger 23.20 GMT den 4 november. Positionen och fartygsidentiteten talar för samma händelse, men tidpunkterna skiljer cirka 65 minuter.</p>\n<p>UKMTO Warning 197-26, publicerad den 6 november, gäller en separat händelse omkring 16 nautiska mil öster om Khasab i Oman. UKMTO:s publika sammanfattning beskriver en tidsfördröjd rapport från befälhavaren på ett utgående tankfartyg om en explosion vid vattenlinjen på babordssidan. Besättningen var säker och räknad, och fartyget fortsatte under egen maskin. UKMTO offentliggjorde inte fartygets identitet eller någon fastställd orsak. Händelsen ska inte blandas ihop med attacken mot VELOS SAPPHIRE.</p>\n<p>En ny produkt, UKMTO Advisory 198-26, daterad den 7 november, återges i en sekundär transkription som en rapport om en incident mellan ett bulkfartyg och militära styrkor omkring 18 nautiska mil öster om Khor Fakkan i Omanbukten. Rapportens händelsetid anges som TBC och besättningens status, skador och miljöpåverkan som okända vid publiceringen. Produkten ska vara en <em>Advisory</em>, inte en <em>Attack Warning</em>. Den tillgängliga transkriptionen anger att källraden är ”Military authorities”; original-PDF:en har inte kunnat hämtas direkt i denna kontroll.</p>\n<p>CENTCOM:s separata uttalande samma dag namnger M/V Huda och beskriver att fartyget slogs ut i Omanbukten. Datum, fartygstyp och geografisk beskrivning gör det sannolikt att UKMTO 198-26 och CENTCOM:s Huda-uttalande avser samma händelse. Men UKMTO-transkriptionen namnger inte Huda och dess källrad är militär myndighet, inte fartygets befälhavare. Matchningen är därför en redaktionell inferens, inte en oberoende bekräftelse av fartygsidentiteten. <strong>OBEKRÄFTAT:</strong> Huda:s besättning, skador och miljöpåverkan är fortfarande inte självständigt fastställda i de öppna källor som kontrollerats.</p>\n<p>Den 30 oktober rapporterade Reuters, med hänvisning till UKMTO och flera säkerhetskällor, att tankfartyget Louise 1 träffats av två så kallade limpetminor nära Khasab i Oman. En brand uppstod i maskinrummet, men besättningen var oskadd, branden släcktes och fartyget kunde fortsätta. Händelsen visade att hotet inte enbart består av stora sjöminor: även små farkoster och fästanordningar mot fartygsskrov kan skapa betydande risker.</p>\n<p>Parallellt har Irans revolutionsgarde (IRGC) lämnat uppgifter om fartyg som ska ha träffats av minor eller fattat eld. Den 4 november återgav Reuters ett IRGC-påstående om fyra tankfartyg som skulle ha förstörts av minor och två fartyg som skulle ha stoppats. Den 5 november rapporterade Reuters att IRGC hävdade att två tankfartyg hade träffat sjöminor och att ytterligare ett fartyg hade fattat eld efter att ha använt rutter som Iran betecknade som otillåtna. Vissa återgivningar identifierade det tredje fartyget som en bogserbåt, men fartygsidentiteten och händelseförloppet kunde inte självständigt fastställas. Detta är partsuppgifter, inte bekräftade händelser.</p>\n<p>Dessa uppgifter ska inte läggas ihop till ett bekräftat antal förstörda fartyg. I det material som granskats här finns ingen oberoende bekräftelse av fartygens identiteter, skador eller det påstådda händelseförloppet. UKMTO:s dokumenterade incidentrapporter från den 3 november är separata händelser och får inte blandas ihop med IRGC:s påståenden.</p>\n<h3>Lägre riskpris betyder inte fred eller normal sjöfart</h3>\n<p>Hormuz är inte bara en smal passage på kartan. Det är en punkt där energihandel, försäkringsmarknad, militär närvaro och diplomatiska villkor möts. När ett land begränsar vilka rutter som anses tillåtna, när fartyg träffas eller bordas och när redare måste räkna med högre premier, kan handeln fortsätta – men med en annan kostnadsstruktur och en annan grad av politisk kontroll.</p>\n<p>Sydkoreas plan visar att regeringar redan tänker längre än nästa oljeprisrörelse. De bygger kapacitet för att skydda sjöfart och, om ett framtida mandat och säkerhetsläge tillåter det, bidra till att röja minor efter striderna. Samtidigt håller Seoul en tydlig gräns mot att bli en stridande part.</p>\n<p>Marknaden kan prisa in ett fredsavtal innan något sådant finns. Sjöfarten måste däremot förhålla sig till de fartyg som faktiskt passerar, de incidenter som rapporteras och de risker som försäkringsbolagen sätter pris på. Det är därför ett fallande oljepris inte i sig bevisar att Hormuz är säkert – lika lite som en militär förberedelse bevisar att en ny strid är nära.</p>\n<p>Den centrala frågan är inte bara när trafiken återgår till det normala, utan vem som då sätter villkoren för passage, säkerhet, försäkring och kontroll.</p>\n<h3>Nya USA-angrepp på Qeshm – medling fortsätter</h3>\n<p>Den 6 november uppgav USA:s president Donald Trump inför reportrar att amerikanska styrkor genomfört ett nytt begränsat angrepp mot ett iranskt luftvärnssystem. Trump beskrev operationen som mindre och sade att systemet slagits ut på några minuter. Associated Press återger uttalandet och rapporterar att iransk statlig media samtidigt rapporterade två explosioner i Suza-området på Qeshmön, i anslutning till Hormuzsundet. The Guardian återger samma presidentuttalande. Al Jazeera rapporterade den 7 november att en CENTCOM-tjänsteman sade att läget var ”relativt lugnt” och att kommandot inte hade någon ytterligare kommentar till explosionerna på Qeshm. Det är inte en operativ bekräftelse av Trumps målbeskrivning. Trump lämnade enligt AP inga ytterligare detaljer om målet. Någon separat detaljerad operativ redogörelse från CENTCOM eller Pentagon för just detta angrepp har inte hittats.</p>\n<p>Det är därför viktigt att skilja tre nivåer: presidentens offentliga uppgift om att ett angrepp genomförts, iranska mediers rapportering om explosioner på Qeshm och den ännu ofullständiga offentliga skadebilden. De tillgängliga uppgifterna räcker inte för att fastställa exakt träffpunkt, skadornas omfattning eller om andra mål träffades. Angreppet ska inte heller förväxlas med de tidigare amerikanska insatser som beskrivits som defensiva under veckan.</p>\n<p>Samtidigt fortsätter den diplomatiska kanalen. Qatars premiärminister Sheikh Mohammed bin Abdulrahman Al-Thani sade den 7 november att medlingen mellan Washington och Teheran fortsätter, att betydande framsteg har gjorts och att han tror att en uppgörelse är möjlig. Han sade att parterna inte kan vänta på ett perfekt avtal. Detta är Qatars beskrivning av förhandlingarnas läge, inte ett besked om att ett avtal har undertecknats eller att sjöfarten har fått ett nytt bindande passagearrangemang.</p>\n<p>Associated Press rapporterade den 7 november, med hänvisning till två anonyma regionala regeringsföreträdare, om ett möjligt tvådagars så kallat bryggförslag från qatariska medlare. Enligt dessa uppgifter skulle USA först lätta på blockaden av iranska hamnar och frigöra delar av frysta iranska tillgångar, medan Iran i gengäld skulle tillåta IAEA-inspektörer till anläggningar som bombats av USA och Israel. Under den andra dagen skulle Iran åter öppna Hormuz enligt en modifierad överenskommelse mellan Iran och Oman som ännu inte godkänts av USA. AP:s uppgifter bygger på anonyma tjänstemän; någon offentlig fullständig förslagstext har inte presenterats. Förslaget ska därför beskrivas som rapporterat och under diskussion, inte som ett beslutat avtal.</p>\n<p>Detta tvådagarsförslag ska hållas isär från Irans eget sjudagarsförslag som Reuters rapporterade om den 7 november. Enligt Reuters har Teheran sedan september föreslagit att Washington ska häva blockaden av iranska hamnar, frigöra tillgångar och godkänna en Iranstödd rutt genom Hormuz, varefter sundet skulle öppnas. Reuters uppger att president Trump hittills avvisat den planen. De två förslagen har olika uppgiftskällor och villkor och får inte blandas samman.</p>\n<p>Den politiska bilden är därmed dubbel: ett nytt amerikanskt angrepp har offentliggjorts samtidigt som Qatar beskriver fortsatt diplomatiskt framsteg. Det finns ännu inget offentligt avtal som fastställer kontrollen över rutterna, minröjning, inspektioner, sanktioner, blockadens status eller garantier för kommersiell sjöfart. För redare och besättningar är det de konkreta villkoren och verifierbara säkerhetsläget – inte förhandlarnas optimism – som avgör om passagen är användbar.</p>\n<h2>M/V Huda: amerikanskt våld mot ett kommersiellt fartyg</h2>\n<p><strong>Händelsedatum:</strong> 7 november 2026. <strong>Publiceringsdatum:</strong> CENTCOM den 7 november; Reuters och Associated Press samma dag.</p>\n<p><strong>PRIMÄRKÄLLA – CENTCOM:</strong> U.S. Central Command uppgav att amerikanska styrkor slagit ut det St Kitts-flagade kommersiella lastfartyget M/V Huda i Omanbukten. Enligt CENTCOM hade fartyget besökt en iransk hamn och försökt lämna regionens vatten trots upprepade varningar om den amerikanska blockaden. Ett amerikanskt militärflygplan avfyrade precisionsvapen mot aktern efter att besättningen instruerats att lämna de utpekade utrymmena. CENTCOM beskrev fartyget som obrukbart.</p>\n<p><strong>OBEROENDE BEKRÄFTELSE – Reuters och AP:</strong> Båda nyhetsorganisationerna återgav CENTCOM:s besked. Det bekräftar att myndigheten offentliggjort angreppet, men fastställer inte självständigt att fartyget brutit mot blockaden, varför det besökt den iranska hamnen eller vilken last det hade.</p>\n<p><strong>OBEKRÄFTAT:</strong> Fartygets IMO-nummer, registrerade ägare, operatör, last och besättningens faktiska tillstånd efter angreppet har inte kunnat fastställas i de öppna källor som granskats. Att besättningen instruerats att lämna målområdet är inte samma sak som oberoende bekräftelse av att alla kom i säkerhet. Fartyget beskrivs som utslaget, inte som sänkt.</p>\n<p><strong>PARTSUPPGIFT – CENTCOM:s totalsiffror:</strong> I samma meddelande uppgav CENTCOM att 147 handelsfartyg omdirigerats sedan juli, att fem fartyg slagits ut efter att inte ha följt order och att tio iranska kommersiella oljetankfartyg förstörts. Dessa totalsiffror är amerikanska myndighetsuppgifter och har inte verifierats oberoende i denna granskning.</p>\n<p>Händelsen markerar ett steg från varningar och omdirigering till användning av militärt våld mot ett kommersiellt fartyg i samband med blockadens verkställighet. Den amerikanska beteckningen ”blockadöverträdelse” är en partsbeskrivning; den måste prövas mot fartygets faktiska rutt, last, ägande, flaggstatens position och den rättsliga grunden för blockaden.</p>\n<h2>Blockaden flyttar från havet till landvägarna</h2>\n<p><strong>Händelsedatum:</strong> 7 november 2026. <strong>Publiceringsdatum:</strong> CENTCOM och Reuters den 7 november.</p>\n<p><strong>PRIMÄRKÄLLA – CENTCOM:s meddelande:</strong> CENTCOM-chefen amiral Brad Cooper beslutade den 7 november att inrätta Task Force Iron Gate, en intern stab med omkring 20 civila och militära medarbetare baserad i Tampa, Florida. Uppdraget är att samordna med andra amerikanska myndigheter för att begränsa transport av avancerade vapensystem, teknik med dubbla användningsområden, sanktionsbelagt material och olagliga intäktsflöden över Irans landgränser och Kaspiska havet. Det är en samordningsstab, inte ett offentliggjort beslut om att placera amerikanska trupper vid gränsövergångar.</p>\n<p><strong>OBEROENDE UNDERSÖKNING – Reuters:</strong> En Reuters-granskning publicerad samma dag uppgav att ett nätverk knutet till iranska militära organ hade importerat hårdvara, sprängämnen och tunga lastbilar till ett värde av minst 2 miljarder dollar sedan januari 2025. Reuters beskrev flera breda transportkategorier: sjöfrakt över Kaspiska havet från Ryssland, lastbilstransporter från Centralasien och fraktflyg från Kina. Enligt en amerikansk tjänsteman väntas samordningen även omfatta finans-, utrikes- och justitiemyndigheter samt underrättelseorgan. De enskilda transaktionerna och nätverkets juridiska motparter behöver följas mot tull-, sanktions- och bolagsdokument.</p>\n<p><strong>PARTSUPPGIFT:</strong> CENTCOM hävdar att den marina blockaden hittills hindrat Iran från att exportera råolja till ett värde över 25 miljarder dollar. Det är en amerikansk myndighetsuppskattning, inte en oberoende reviderad förlustsiffra. Den nya staben visar däremot att Washington nu beskriver blockaden som ett bredare försörjnings- och sanktionsarbete, inte enbart som kontroll av fartyg till och från iranska hamnar.</p>\n<p>För Hormuzgranskningen är den centrala frågan hur en marin blockad kopplas till landbaserad handel, sekundära sanktioner och civil sjöfart i Kaspiska havet. Task Force Iron Gate är inte i sig bevis för att alla kommersiella landflöden stoppas eller att någon särskild gränsövergång stängts. Det kräver separata beslut och dokumentation.</p>\n<h2>Saudiarabiens östra provins: varning hävs efter missiluppgift</h2>\n<p><strong>Händelsedatum:</strong> 8 november 2026. <strong>Publiceringsdatum:</strong> Reuters 8 november 2026 kl. 03.11 UTC.</p>\n<p><strong>PRIMÄRKÄLLA – Saudi Civil Defence, återgiven av Reuters:</strong> Civilförsvaret hävde varningar i Dhahran, Dammam, Abqaiq och Al-Ahsa kort efter att ha varnat för potentiell fara. Reuters rapporterade inte om någon bekräftad träff eller skada på oljeanläggningar. <a href='https://www.reuters.com/business/aerospace-defense/saudi-civil-defence-gives-all-clear-after-alerts-eastern-province-2026-11-08/' target='_blank' rel='noopener noreferrer'>Reuters – varningarna hävs i östra provinsen</a>.</p>\n<p><strong>PARTSUPPGIFT – den Saudi-ledda koalitionen:</strong> Kort efter all-clear uppgav koalitionen att den hade avlyssnat en ballistisk robot som avfyrats av Houthirörelsen mot den östra regionen. Någon oberoende bekräftelse av robotens avfyrning, avvärjning eller eventuella skador har inte identifierats i denna kontroll.</p>\n<p>Dhahran är plats för Saudi Aramcos huvudkontor och östra provinsen rymmer merparten av landets olje- och gasreserver. Den geografiska kopplingen gör varningen relevant för energiflödena, men är inte i sig bevis för ett angrepp på Aramco eller en oljeanläggning. Händelsen är inte en UKMTO-incident och räknas inte in i IMO:s fartygsattacker.</p>\n<h2>IRGC:s minpåstående: ingen ny incident räknas</h2>\n<p>Irans revolutionsgardes flotta har åter uppgett att två oljetankfartyg fattat eld efter att ha träffat minor på en rutt som Iran beskriver som otillåten. Reuters bekräftar att IRGC lämnat uppgiften, inte att minträffarna eller bränderna inträffat. Fartygsnamn, IMO-nummer, flaggstat, operatör, position, besättningsstatus och oberoende skade- eller räddningsuppgifter saknas i den rapportering som kontrollerats.</p>\n<p><strong>PARTSUPPGIFT / OBEKRÄFTAD:</strong> Det är oklart om uttalandet gäller nya fartyg, samma fartyg som i tidigare uttalanden eller en återpublicering av ett äldre påstående. Det räknas därför inte som en ny verifierad incident och läggs inte till någon incidenttotal.</p>\n<h2>Källor och dokumentation</h2>\n<h3>Primärkällor</h3>\n<ul>\n<li><a href=\"https://www.ukmto.org/-/media/ukmto/products/20261106-ukmto_vra_overview_u.pdf?rev=26469c3751c649ea9c7214a0bd063c0c\" target=\"_blank\" rel=\"noopener noreferrer\">UKMTO – Voluntary Reporting Area Weekly Overview No. 14, 6 november 2026</a></li>\n<li><a href=\"https://www.ukmto.org/-/media/ukmto/products/jmic_advisory_update_111_05-nov.pdf?rev=de54e3b88ef24dd3a3c3cb0a215b1acf\" target=\"_blank\" rel=\"noopener noreferrer\">JMIC – Advisory Update 111, 5 november 2026</a></li>\n<li><a href=\"https://www.ukmto.org/-/media/ukmto/products/20261106-ukmto_warning-197-26.pdf?rev=c53718e903cc45659052993058647de4\" target=\"_blank\" rel=\"noopener noreferrer\">UKMTO – Warning 197-26, 6 november 2026</a></li>\n<li><a href=\"https://www.imo.org/en/mediacentre/pressbriefings/pages/imo-council-c138-urges-stronger-protection-of-seafarers-amid-threats-to-global-shipping-.aspx\" target=\"_blank\" rel=\"noopener noreferrer\">IMO – rådets uttalande om den 25:e sjömansförlusten, 6 november 2026</a></li>\n<li><a href=\"https://www.imo.org/en/mediacentre/hottopics/pages/middle-east-highlighted-incidents.aspx\" target=\"_blank\" rel=\"noopener noreferrer\">IMO – regional lista över bekräftade incidenter</a></li>\n<li><a href=\"https://x.com/CENTCOM/status/2119059918120526182\" target=\"_blank\" rel=\"noopener noreferrer\">CENTCOM – offentlig uppgift om M/V Huda, 7 november 2026</a></li>\n<li><a href=\"https://mofa.gov.qa/en/qatar/latest-articles/latest-news/details/2026/11/03/advisor-to-prime-minister--official-spokesperson-for-ministry-of-foreign-affairs--qatar-continues-its-efforts-to-bridge-gap-between-washington--tehran\" target=\"_blank\" rel=\"noopener noreferrer\">Qatars utrikesministerium – medlingskontakter, 3 november 2026</a></li>\n<li><a href=\"https://mofa.gov.qa/en/qatar/latest-articles/latest-news/details/2026/11/05/pm--minister-of-foreign-affairs-reaffirms-support-for-diplomacy-in-call-with-iran-fm\" target=\"_blank\" rel=\"noopener noreferrer\">Qatars utrikesministerium – samtal med Irans utrikesminister, 5 november 2026</a></li>\n<li><a href=\"https://www.fm.gov.om/en/53722/\" target=\"_blank\" rel=\"noopener noreferrer\">Omans utrikesministerium – gemensamt Oman–Iran-uttalande, 25 augusti 2026</a></li>\n<li><a href=\"https://www.eia.gov/international/content/analysis/special_topics/World_Oil_Transit_Chokepoints/\" target=\"_blank\" rel=\"noopener noreferrer\">U.S. Energy Information Administration – World Oil Transit Chokepoints</a></li>\n</ul>\n<h3>Oberoende och kompletterande källor</h3>\n<ul>\n<li><a href=\"https://www.reuters.com/world/one-seafarer-killed-missile-attack-tanker-gulf-2026-11-06/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – dödsfallet ombord på VELOS SAPPHIRE, 6 november 2026</a></li>\n<li><a href=\"https://www.reuters.com/world/middle-east/us-military-says-it-disabled-cargo-vessel-gulf-oman-2026-11-07/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – CENTCOM:s uppgift om M/V Huda, 7 november 2026</a></li>\n<li><a href=\"https://www.gmanetwork.com/news/pinoyabroad/dispatch/1008636/dmw-filipino-seafarer-killed-another-hurt-in-persian-gulf-tanker-attack/story/\" target=\"_blank\" rel=\"noopener noreferrer\">GMA News – DMW:s motuppgift om en skadad filippinsk sjöman, 7 november 2026</a></li>\n<li><a href=\"https://regulasshipping.com/blog/ukmto-198-26-records-a-bulk-carrier-incident-18-nm-east-of-khor-fakkan/\" target=\"_blank\" rel=\"noopener noreferrer\">Regulas Shipping – sekundär transkription av UKMTO Advisory 198-26, 7 november 2026; original-PDF inte direkt hämtad</a></li>\n<li><a href=\"https://www.forth.news/lists/centcom/Cgoet5KhSp6nWZnwnUeuR\" target=\"_blank\" rel=\"noopener noreferrer\">CENTCOM – Task Force Iron Gate, myndighetsrelease återgiven i Forth, 7 november 2026</a></li>\n<li><a href=\"https://www.investing.com/news/world-news/exclusiveexpanding-on-naval-blockade-us-military-looks-to-restrict-iranian-land-commerce-5009890\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – Task Force Iron Gate och landbaserade leveranskedjor, 7 november 2026</a></li>\n<li><a href=\"https://apnews.com/article/bc902d3400cb5d022f8bafd247ef975b\" target=\"_blank\" rel=\"noopener noreferrer\">Associated Press – M/V Huda, 7 november 2026</a></li>\n<li><a href=\"https://www.reuters.com/world/middle-east/qatar-says-its-mediation-efforts-between-us-iran-continue-prevent-escalation-2026-11-07/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – Qatars medlingsuttalande, 7 november 2026</a></li>\n<li><a href=\"https://www.theguardian.com/world/2026/nov/07/strait-of-hormuz-qatar-plan-iran-nuclear-inspections\" target=\"_blank\" rel=\"noopener noreferrer\">The Guardian – rapporterat qatariskt förslag, 7 november 2026</a></li>\n<li><a href=\"https://www.reuters.com/world/middle-east/explosions-heard-irans-qeshm-island-iranian-media-reports-2026-11-07/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – motstridiga uppgifter om explosioner på Qeshm, 7 november 2026</a></li>\n<li><a href=\"https://www.reuters.com/world/asia-pacific/south-korea-expand-anti-piracy-unit-operations-closer-strait-hormuz-2026-11-05/\" target=\"_blank\" rel=\"noopener noreferrer\">Reuters – Sydkoreas planerade utvidgning av Cheonghae-enheten, 5 november 2026</a></li>\n</ul>\n<p><strong>Redaktionell avgränsning:</strong> UKMTO, JMIC och IMO använder olika geografiska områden, tidsperioder och verifieringsdefinitioner. Deras totalsiffror ska inte adderas. Diplomatiska förslag som återges av medier är inte avtalstext. Ingen ansvarig aktör har fastställts för VELOS SAPPHIRE eller UKMTO 197-26. Uppgifterna om M/V Huda:s blockadöverträdelse och IRGC:s minträffar återges som partsuppgifter där det är relevant.</p>"];

