function route(){const p=decodeURIComponent(location.hash.slice(1)||'/');if(p==='/'){app.innerHTML=`<section class="front-grid"><div class="lead-story"><div class="kicker">PÅGÅENDE GRANSKNING · MAKT <span class="red-dot">●</span> UNDER RESEARCH</div><h1>Vem äger infrastrukturen bakom den nya makten?</h1><p class="standfirst">När data, offentliga institutioner och artificiell intelligens vävs samman växer en ny sorts maktstruktur fram. Vi granskar aktörerna, avtalen och beroendena.</p><div class="byline">REDAKTIONEN · PÅGÅENDE GRANSKNING</div><a class="read-link" href="#/artikel/palantir-offentlig-makt">FÖLJ ARBETET ↗</a></div><aside class="front-note"><div class="stamp">FT<br><small>001</small></div><p class="note-label">TIDNINGENS UPPDRAG</p><p>Makt ska granskas. Kapitalet ska förstås. Historien ska bevaras.</p><div class="note-rule"></div><p class="small">Fakta först. Källor öppet. Analys tydligt åtskild från belagda uppgifter.</p></aside></section><div class="section-head"><h2>DETTA UNDERSÖKER VI</h2><span>01 — 15 / REDAKTIONELL PLAN</span></div><section class="article-grid">${renderCards(articles)}</section><section class="lower-grid"><div class="forebears"><div class="section-head"><h2>VÅRA FÖREGÅNGARE</h2><a href="#/foregangare">LÄS MER ↗</a></div><p class="forebear-names">GUTENBERG · LINNÉ · VOLTAIRE<br>PARASKEVI · CHARBEL<br>ETT SJÄTTE NAMN FASTSTÄLLS FÖRE PUBLICERING</p><p class="small">En återkommande hyllning till tryckkonst, vetenskap, filosofi, bildning och andligt kulturarv.</p></div></section>`;return}
if(p.startsWith('/artikel/')){const id=p.split('/')[2],a=articles.find(x=>x.id===id);if(!a){shell('<a class="back" href="#/">← TILLBAKA</a><h1>Artikeln hittades inte</h1>');return}const paras=articleBodies[id]||[];shell(`<a class="back" href="#/">← TILLBAKA TILL TIDNINGEN</a><div class="tag">${a.tag}</div><h1>${a.title}</h1><p class="standfirst">${a.desc}</p><div class="byline">FOLKTRIBUNALENS REDAKTION · ${a.date||'PUBLICERAD 7 NOVEMBER 2026'}</div><div class="notice">REDAKTIONELL ANMÄRKNING: Publicerad med öppet redovisade källor och avgränsningar. Uppgifter som ännu saknar offentlig dokumentation presenteras som obesvarade frågor, inte som fastslagna fakta.</div><div class="prose">${paras.map(x=>x.trim().startsWith('<')?x:`<p>${x}</p>`).join('')}<h2>Källor och dokumentation</h2><p>Källor är länkade i respektive artikel. Redaktionella reservationer och öppna kontrollfrågor redovisas i texten.</p></div>`);return}
if(p.startsWith('/kategori/')){const key=p.split('/')[2],map={makt:'Makt',finans:'Finans',resurser:'Resurser',kultur:'Kultur',folk:'Folk'},cat=map[key];shell(`<a class="back" href="#/">← TIDNINGEN</a><h1>${cat||'Avdelning'}</h1><section class="article-grid">${renderCards(articles.filter(a=>a.cat===cat))}</section>`);return}
if(p==='/symbolarkiv'){shell(`<a class="back" href="#/">← TIDNINGEN</a><div class="tag">REFERENSBIBLIOTEK</div><h1>Symbolerna bär historien</h1><p class="standfirst">Ett växande arkiv över symboler, kors, sigill och emblem. Historiska belägg skiljs från tradition och tolkning.</p><div class="article-grid"><article class="article-card"><div class="symbol-glyph">☩</div><h3>Det östortodoxa korset</h3><p>Tvärbjälkar, titulus och den lutande fotbrädan – historiska variationer och teologiska tolkningar.</p><span class="status">UNDER KÄLLARBETE</span></article><article class="article-card"><div class="symbol-glyph">♱</div><h3>Golgota och Adams skalle</h3><p>Golgota som platsnamn, korsets ikonografi och traditionen om Kristus som den nye Adam.</p><span class="status">TRADITION SKILJS FRÅN ARKEOLOGI</span></article><article class="article-card"><div class="symbol-glyph">♧</div><h3>Libanons ceder</h3><p>Nationalemblem, bibliska texter och symbolen för styrka, beständighet och land.</p><span class="status">UNDER KÄLLARBETE</span></article><article class="article-card"><div class="symbol-glyph">⌘</div><h3>Bomärket från Oxkangar</h3><p>Granngårdens äldre gårds- och familjemärke med hakkorsform – ett lokalt identitetstecken som måste förstås i sitt historiska sammanhang.</p><a href="#/bomarken-oxkangar">LÄS UNDERSÖKNINGEN ↗</a><span class="status">NYTT REDAKTIONELLT SPÅR</span></article></div>`);return}
if(p==='/foregangare'){shell(`<a class="back" href="#/">← TIDNINGEN</a><h1>Våra föregångare</h1><p class="standfirst">En återkommande hyllning till människor som format tryckkonst, vetenskap, idéhistoria, andligt liv och nationellt kulturarv.</p><div class="prose"><p>Johannes Gutenberg · Carl von Linné · Voltaire · Sankta Paraskevi · Sankt Charbel.</p><p>Ett sjätte namn återstår att identifiera innan det kan publiceras. Inget annat namn används som ersättning.</p><p>Varje porträtt ska innehålla kort biografi, historisk kontext och ett autentiskt citat med spårbar källa. Citat som ännu inte har kontrollerats märks som tillskrivna och publiceras inte som säkra ordalydelser.</p></div>`);return}
if(p==='/arkiv'){shell(`<a class="back" href="#/">← TIDNINGEN</a><h1>Arkiv</h1><p class="standfirst">Utgåvor och publicerade arbeten samlas här. Första utgåvan är under uppbyggnad.</p><div class="notice">UTGÅVA 001 · REDAKTIONELL PLAN · PUBLICERINGSARKIVET ÖPPNAS NÄR FÖRSTA ARTIKLARNA HAR GODKÄNTS.</div>`);return}
if(p==='/om-oss'){shell(`<div class="about-hero"><div class="about-seal">✠<span>FT</span></div><div class="about-copy"><div class="tag">OM OSS · REDAKTIONEN</div><h1>En röst för historia, makt och människan.</h1><p class="standfirst">FOLKTRIBUNALEN är en oberoende redaktionell plattform för undersökande journalistik, historiskt minne och självständig analys.</p><div class="about-motto">VERITAS · MEMORIA · RESPONSABILITAS</div></div></div><div class="editor-profile"><div class="editor-art" role="img" aria-label="Heraldisk renässansillustration av chefredaktören"><div class="editor-art-inner"><div class="editor-crown">✥</div><div class="editor-title">CHEFREDAKTÖR</div><div class="editor-name">FOLKTRIBUNALEN</div><div class="editor-devise">JESUS ÄR TSAR</div></div></div><div class="editor-bio"><div class="tag">REDAKTIONELL LEDNING</div><h2>Chefredaktören</h2><p>Ansvarar för tidningens redaktionella riktning, publicistiska prioriteringar och arbetet med att skilja dokumenterade uppgifter från analys och historisk tolkning.</p><p>FOLKTRIBUNALEN förenar granskning av institutionell makt och kapital med intresse för kulturarv, idéhistoria och Europas religiösa och kulturella kontinuitet.</p><blockquote>”Makt ska granskas. Kapitalet ska förstås. Historien ska bevaras.”</blockquote><div class="editor-signature">FOLKTRIBUNALEN <span>✠</span></div></div></div><div class="about-pillars"><article><span>01</span><h3>Oberoende</h3><p>Redaktionella slutsatser ska vila på belägg, inte lojaliteter.</p></article><article><span>02</span><h3>Källkritik</h3><p>Primärkällor prioriteras. Osäkerhet och motstridiga uppgifter redovisas.</p></article><article><span>03</span><h3>Historiskt minne</h3><p>Kulturarv och människors berättelser behandlas med respekt och sammanhang.</p></article></div>`);return}
if(p==='/redaktion'){location.href='/admin.html';return}if(p==='/redaktion-demo'){const saved=JSON.parse(localStorage.getItem('ft-status')||'{}');shell(`<a class="back" href="#/">← TIDNINGEN</a><div class="tag">INTERN DEMO · LOKAL WEBBLÄSARE</div><h1>Redaktionens arbetsbord</h1><p class="standfirst">Översikt över de nio första artikelprojekten.</p><div class="notice">Detta är en gränssnittsprototyp. Statusändringar sparas endast i den här webbläsaren. Inloggning, central databas, riktig redaktionell inkorg och publiceringsflöde byggs i nästa backendsteg.</div><div class="admin-list">${articles.map(a=>`<div class="admin-item"><div><div class="tag">${a.tag}</div><strong>${a.title}</strong><div class="status">${saved[a.id]||'PLANERAD'}</div></div><button data-id="${a.id}" ${saved[a.id]==='GODKÄND FÖR PUBLICERING'?'disabled':''}>${saved[a.id]==='GODKÄND FÖR PUBLICERING'?'GODKÄND':'MARKERA GODKÄND'}</button></div>`).join('')}</div>`);document.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>{const s=JSON.parse(localStorage.getItem('ft-status')||'{}');s[b.dataset.id]='GODKÄND FÖR PUBLICERING';localStorage.setItem('ft-status',JSON.stringify(s));route()}));return}
shell('<a class="back" href="#/">← TILLBAKA</a><h1>Sidan hittades inte</h1>')}
